filldraw(shift(sqrt(3)*2.5,4.5)*hex, darkcolor,black);
filldraw(shift(sqrt(3)*2,6)*hex, darkcolor,black);
filldraw(shift(sqrt(3),6)*hex, darkcolor,black);
